import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def extract_document_layout(file_path: str) -> dict:
    """
    Extracts blocks, lines, tables, and layout elements from a document using Azure AI Document Intelligence.

    Args:
        file_path: The path to the document file (e.g., PDF, JPG, PNG).

    Returns:
        A dictionary containing the extracted layout information.
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(file_path, "rb") as f:
        poller = document_intelligence_client.begin_analyze_document(
            "prebuilt-layout", analyze_request=f, content_type="application/octet-stream"
        )
    result: AnalyzeResult = poller.result()

    extracted_data = {
        "paragraphs": [],
        "tables": []
    }

    if result.paragraphs:
        for paragraph in result.paragraphs:
            extracted_data["paragraphs"].append({
                "role": paragraph.role,
                "content": paragraph.content,
                "bounding_regions": [
                    {
                        "page_number": region.page_number,
                        "polygon": [
                            {"x": point.x, "y": point.y}
                            for point in region.polygon
                        ],
                    }
                    for region in paragraph.bounding_regions
                ]
            })

    if result.tables:
        for table in result.tables:
            table_data = {
                "row_count": table.row_count,
                "column_count": table.column_count,
                "cells": [],
                "bounding_regions": [
                    {
                        "page_number": region.page_number,
                        "polygon": [
                            {"x": point.x, "y": point.y}
                            for point in region.polygon
                        ],
                    }
                    for region in table.bounding_regions
                ]
            }
            for cell in table.cells:
                table_data["cells"].append({
                    "content": cell.content,
                    "row_index": cell.row_index,
                    "column_index": cell.column_index,
                    "row_span": cell.row_span,
                    "column_span": cell.column_span,
                    "kind": cell.kind
                })
            extracted_data["tables"].append(table_data)

    return extracted_data
